    private void configureBingoSelector() {
        bingoSelector.setRenderer(createBingoRenderer());
        bingoSelector.addActionListener(createBingoSelectionListener());
        bingoSelector.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        bingoSelector.setForeground(Color.WHITE);
        bingoSelector.setFocusable(false);
    }

    private DefaultListCellRenderer createBingoRenderer() {
        return new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(JList<?> list, Object value, int index,
                                                          boolean isSelected, boolean cellHasFocus) {
                super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
                if (value instanceof Bingo) {
                    Bingo bingo = (Bingo) value;
                    StringBuilder text = new StringBuilder(bingo.getTitle());

                    // Show if the bingo is locked or visible
                    if (bingo.isLocked()) {
                        text.append(" [Locked]");
                    }

                    // Show pin icon if this bingo is pinned
                    if (bingo.getId().toString().equals(plugin.getConfig().pinnedBingoId())) {
                        text.append(" 📌");
                    }

                    setText(text.toString());
                }

                if (isSelected) {
                    setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
                } else {
                    setBackground(ColorScheme.DARKER_GRAY_COLOR);
                }
                setForeground(Color.WHITE);

                return this;
            }
        };
    }

    private ActionListener createBingoSelectionListener() {
        return e -> {
            Bingo selectedBingo = (Bingo) bingoSelector.getSelectedItem();
            if (selectedBingo != null) {
                // Update the current bingo in the plugin first to ensure the overlay gets updated
                plugin.selectBingo(selectedBingo);
            }
        };
    }

    private JButton createShowBingoBoardButton() {
        JButton button = new JButton("Show Bingo Board");
        button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        button.setForeground(Color.WHITE);
        button.setFocusPainted(false);
        button.addActionListener(e -> {
            Bingo selectedBingo = (Bingo) bingoSelector.getSelectedItem();
            if (selectedBingo != null) {
                showBingoBoardWindow(selectedBingo);
            }
        });
        return button;
    }

    private void showBingoBoardWindow(Bingo bingo) {
        SwingUtilities.invokeLater(() -> {
            if (bingoBoardWindow != null) {
                bingoBoardWindow.dispose();
            }

            bingoBoardWindow = new BingoBoardWindow(plugin, bingo);
            bingoBoardWindow.setVisible(true);
        });
    }

    public void updateEventsList(List<EventData> events) {
        SwingUtilities.invokeLater(() -> {
            // Store current selections
            EventData selectedEvent = (EventData) eventSelector.getSelectedItem();
            String selectedEventId = selectedEvent != null ? selectedEvent.getId().toString() : null;
            String pinnedBingoId = plugin.getConfig().pinnedBingoId();

            // Update the event selector model
            DefaultComboBoxModel<EventData> model = new DefaultComboBoxModel<>();
            for (EventData event : events) {
                model.addElement(event);
                // If this event contains the pinned bingo, select it
                if (!pinnedBingoId.isEmpty() && event.getBingos().stream()
                        .anyMatch(b -> b.getId().toString().equals(pinnedBingoId))) {
                    selectedEventId = event.getId().toString();
                }
            }
            eventSelector.setModel(model);

            // Restore selection if possible
            if (selectedEventId != null) {
                for (int i = 0; i < model.getSize(); i++) {
                    EventData event = model.getElementAt(i);
                    if (event.getId().toString().equals(selectedEventId)) {
                        eventSelector.setSelectedIndex(i);
                        break;
                    }
                }
            } else if (model.getSize() > 0) {
                eventSelector.setSelectedIndex(0);
            }

            // Update UI state
            eventSelector.setEnabled(model.getSize() > 0);
            reloadEventsButton.setEnabled(true);
            loadingLabel.setVisible(false);
        });
    }

    // Method to update event details with enhanced information
    public void updateEventDetails(EventData eventData) {
        if (eventData == null) {
            eventDetailsPanel.setVisible(false);
            bingoPanel.setVisible(false);
            return;
        }

        // Update bingo selector
        bingoSelector.removeAllItems();
        String pinnedBingoId = plugin.getConfig().pinnedBingoId();
        Bingo pinnedBingo = null;

        // First pass to find pinned bingo if it exists
        if (!pinnedBingoId.isEmpty()) {
            for (Bingo bingo : eventData.getBingos()) {
                if (bingo.getId().toString().equals(pinnedBingoId)) {
                    pinnedBingo = bingo;
                    break;
                }
            }
        }

        // Add all bingos, with pinned one first if it exists
        if (pinnedBingo != null) {
            bingoSelector.addItem(pinnedBingo);
        }
        for (Bingo bingo : eventData.getBingos()) {
            if (pinnedBingo == null || !bingo.getId().equals(pinnedBingo.getId())) {
                bingoSelector.addItem(bingo);
            }
        }

        // Select pinned bingo if it exists, otherwise first bingo
        if (pinnedBingo != null) {
            bingoSelector.setSelectedItem(pinnedBingo);
        } else if (bingoSelector.getItemCount() > 0) {
            bingoSelector.setSelectedIndex(0);
        }

        // Rest of the event details update...
        // ... existing code ...

        SwingUtilities.invokeLater(() -> {
            // Clear previous event details
            eventDetailsPanel.removeAll();
            bingoSelector.removeAllItems();

            // Build event details panel
            if (eventData != null) {
                // Title panel
                JPanel titlePanel = new JPanel();
                titlePanel.setLayout(new BoxLayout(titlePanel, BoxLayout.Y_AXIS));
                titlePanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
                titlePanel.setAlignmentX(Component.LEFT_ALIGNMENT);
                titlePanel.setBorder(new EmptyBorder(5, 5, 5, 5));

                JLabel titleLabel = new JLabel(eventData.getTitle());
                titleLabel.setFont(FontManager.getRunescapeBoldFont());
                titleLabel.setForeground(new Color(255, 215, 0)); // Gold color
                titleLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
                titlePanel.add(titleLabel);

                // Add status indicator
                JLabel statusLabel = new JLabel(eventData.isLocked() ? "🔒 Locked" : "✅ Active");
                statusLabel.setForeground(eventData.isLocked() ? Color.LIGHT_GRAY : new Color(34, 197, 94));
                statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
                titlePanel.add(statusLabel);

                eventDetailsPanel.add(titlePanel);

                // Event description
                if (eventData.getDescription() != null && !eventData.getDescription().isEmpty()) {
                    JTextArea descriptionArea = new JTextArea(eventData.getDescription());
                    descriptionArea.setWrapStyleWord(true);
                    descriptionArea.setLineWrap(true);
                    descriptionArea.setEditable(false);
                    descriptionArea.setForeground(Color.WHITE);
                    descriptionArea.setBackground(ColorScheme.DARKER_GRAY_COLOR);
                    descriptionArea.setBorder(new CompoundBorder(
                        new MatteBorder(1, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
                        new EmptyBorder(5, 5, 5, 5)
                    ));
                    descriptionArea.setAlignmentX(Component.LEFT_ALIGNMENT);
                    eventDetailsPanel.add(descriptionArea);
                }

                // Info section
                JPanel infoSection = new JPanel();
                infoSection.setLayout(new BoxLayout(infoSection, BoxLayout.Y_AXIS));
                infoSection.setBackground(ColorScheme.DARK_GRAY_COLOR);
                infoSection.setBorder(new EmptyBorder(5, 5, 5, 5));
                infoSection.setAlignmentX(Component.LEFT_ALIGNMENT);

                // Event dates
                if (eventData.getStartDate() != null && eventData.getEndDate() != null) {
                    addInfoLabel(infoSection, "📅 Event dates: " +
                            DATE_FORMAT.format(eventData.getStartDate()) + " - " +
                            DATE_FORMAT.format(eventData.getEndDate()));
                }

                // Prize pool
                if (eventData.getBasePrizePool() > 0) {
                    addInfoLabel(infoSection, "💰 Prize pool: " + formatGpAmount(eventData.getBasePrizePool()));
                    if (eventData.getMinimumBuyIn() > 0) {
                        addInfoLabel(infoSection, "💎 Minimum buy-in: " + formatGpAmount(eventData.getMinimumBuyIn()));
                    }
                }

                // Role
                if (eventData.getRole() != null) {
                    addInfoLabel(infoSection, "👤 Role: " + formatRole(eventData.getRole()));
                }

                // Clan
                if (eventData.getClan() != null) {
                    addInfoLabel(infoSection, "🏰 Clan: " + eventData.getClan().getName());
                }

                // Team
                if (eventData.getUserTeam() != null) {
                    addInfoLabel(infoSection, "👥 Team: " + eventData.getUserTeam().getName());
                    if (eventData.getUserTeam().getMembers() != null && !eventData.getUserTeam().getMembers().isEmpty()) {
                        JPanel membersPanel = new JPanel();
                        membersPanel.setLayout(new BoxLayout(membersPanel, BoxLayout.Y_AXIS));
                        membersPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
                        membersPanel.setBorder(new EmptyBorder(0, 15, 0, 0));
                        membersPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

                        // First add the leader
                        for (TeamMember member : eventData.getUserTeam().getMembers()) {
                            if (member.isLeader()) {
                                String memberText = "• " + member.getRunescapeName() + " 👑";
                                JLabel memberLabel = new JLabel(memberText);
                                memberLabel.setForeground(new Color(255, 215, 0));
                                memberLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
                                membersPanel.add(memberLabel);
                                membersPanel.add(Box.createVerticalStrut(2));
                                break;
                            }
                        }

                        // Then add other members
                        for (TeamMember member : eventData.getUserTeam().getMembers()) {
                            if (!member.isLeader()) {
                                String memberText = "• " + member.getRunescapeName();
                                JLabel memberLabel = new JLabel(memberText);
                                memberLabel.setForeground(Color.WHITE);
                                memberLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
                                membersPanel.add(memberLabel);
                                membersPanel.add(Box.createVerticalStrut(2));
                            }
                        }
                        infoSection.add(membersPanel);
                    }
                }

                // Available boards
                if (eventData.getBingos() != null) {
                    addInfoLabel(infoSection, "🎯 Available boards: " + eventData.getBingos().size());
                }

                eventDetailsPanel.add(infoSection);
                eventDetailsPanel.setVisible(true);

                // Populate bingo selector
                if (eventData.getBingos() != null && !eventData.getBingos().isEmpty()) {
                    for (Bingo bingo : eventData.getBingos()) {
                        bingoSelector.addItem(bingo);
                    }
                    bingoPanel.setVisible(true);
                } else {
                    bingoPanel.setVisible(false);
                }
            } else {
                eventDetailsPanel.setVisible(false);
                bingoPanel.setVisible(false);
            }

            revalidate();
            repaint();
        });
    }

    private void addInfoLabel(JPanel container, String text) {
        JLabel label = new JLabel(text);
        label.setForeground(Color.WHITE);
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        container.add(label);
        container.add(Box.createVerticalStrut(4));
    }

    // Helper method to format GP amounts nicely
    private String formatGpAmount(long amount) {
        if (amount >= 1_000_000_000) {
            return (amount / 1_000_000_000) + "B GP";
        } else if (amount >= 1_000_000) {
            return (amount / 1_000_000) + "M GP";
        } else if (amount >= 1_000) {
            return (amount / 1_000) + "K GP";
        } else {
            return amount + " GP";
        }
    }

    private String formatRole(Role role) {
        if (role == null) return "Participant";

        switch (role) {
            case ADMIN:
                return "Admin";
            case MANAGEMENT:
                return "Manager";
            case PARTICIPANT:
                return "Participant";
            default:
                return role.toString();
        }
    }

    public void displayBingoBoard(Bingo bingo) {
        // Update the bingo board window if it's open
        if (bingoBoardWindow != null && bingoBoardWindow.isVisible()) {
            // Close and reopen with fresh data to ensure a full refresh
            SwingUtilities.invokeLater(() -> {
                bingoBoardWindow.dispose();
                bingoBoardWindow = new BingoBoardWindow(plugin, bingo);
                bingoBoardWindow.setVisible(true);
            });
        }
    }
}

package org.bingoscape;

import net.runelite.api.Client;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import org.bingoscape.models.Bingo;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.*;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.TimeZone;

/**
 * Overlay that displays the codephrase for the currently selected bingo
 */
public class BingoCodephraseOverlay extends OverlayPanel {
    private static final SimpleDateFormat TIME_FORMAT = new SimpleDateFormat("HH:mm:ss");
    private static final int MAX_WIDTH = 200; // Maximum width for the overlay

    private final BingoScapePlugin plugin;
    private final BingoScapeConfig config;
    private final Client client;

    @Inject
    public BingoCodephraseOverlay(Client client, BingoScapePlugin plugin, BingoScapeConfig config) {
        super(plugin);
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        setPriority(0.1f);
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        // Check if overlay is enabled in settings
        if (!config.showCodephraseOverlay()) {
            return null;
        }

        // Check if a bingo is selected
        Bingo currentBingo = plugin.getCurrentBingo();
        if (currentBingo == null || currentBingo.getCodephrase() == null || currentBingo.getCodephrase().trim().isEmpty()) {
            return null;
        }

        // Get all text components that will be displayed
        String title = plugin.getCurrentEvent().getTitle();
        String boardText = "Board: " + currentBingo.getTitle();
        String codephraseText = "Codephrase: " + currentBingo.getCodephrase();
        String timeText = "Time: " + utcNow();

        // Calculate maximum width based on all components
        FontMetrics metrics = graphics.getFontMetrics();
        int maxWidth = Math.max(
            Math.max(metrics.stringWidth(title), metrics.stringWidth(boardText)),
            Math.max(metrics.stringWidth(codephraseText), metrics.stringWidth(timeText))
        );

        // Add some padding
        maxWidth += 20;

        // Add title
        panelComponent.getChildren().add(TitleComponent.builder()
                .text(title)
                .color(new Color(255, 215, 0)) // Gold color
                .build());

        // Add board
        panelComponent.getChildren().add(LineComponent.builder()
                .left("Board:")
                .right(currentBingo.getTitle())
                .rightColor(Color.WHITE)
                .build());

        // Add codephrase
        panelComponent.getChildren().add(LineComponent.builder()
                .left("Codephrase:")
                .right(currentBingo.getCodephrase())
                .rightColor(Color.WHITE)
                .build());

        // Add current time
        panelComponent.getChildren().add(LineComponent.builder()
                .left("Time:")
                .right(utcNow())
                .rightColor(Color.LIGHT_GRAY)
                .build());

        // Set preferred size based on maximum width
        panelComponent.setPreferredSize(new Dimension(maxWidth, 0));

        return super.render(graphics);
    }

    private String utcNow() {
        SimpleDateFormat sdf = new SimpleDateFormat("dd.MM.yyyy HH:mm");
        sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
        return sdf.format(new Date()) + " UTC";
    }
}

package org.bingoscape.services;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;
import org.bingoscape.BingoScapeConfig;
import org.bingoscape.models.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.Arrays;
import java.util.List;
import java.util.UUID;
import java.util.function.Consumer;

@Slf4j
@Singleton
public class BingoScapeApiService {
    private static final MediaType MEDIA_TYPE_PNG = MediaType.parse("image/png");
    private static final MediaType MEDIA_TYPE_JSON = MediaType.parse("application/json");

    private final OkHttpClient httpClient;
    private final Gson gson;
    private final BingoScapeConfig config;

    @Inject
    public BingoScapeApiService(OkHttpClient httpClient, Gson gson, BingoScapeConfig config) {
        this.httpClient = httpClient;
        this.gson = gson;
        this.config = config;
    }

    public void fetchActiveEvents(Consumer<List<EventData>> onSuccess, Consumer<String> onError) {
        if (!hasApiKey()) {
            onError.accept("No API key configured");
            return;
        }

        String apiUrl = config.apiBaseUrl() + "/api/runelite/events";
        Request request = new Request.Builder()
                .url(apiUrl)
                .header("Authorization", "Bearer " + config.apiKey())
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.error("Failed to fetch events", e);
                onError.accept("Failed to fetch events: " + e.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody responseBody = response.body()) {
                    if (!response.isSuccessful() || responseBody == null) {
                        String error = "Unsuccessful response: " + response;
                        log.error(error);
                        onError.accept(error);
                        return;
                    }

                    String jsonData = responseBody.string();
                    EventData[] eventsResponse = gson.fromJson(jsonData, EventData[].class);
                    onSuccess.accept(Arrays.asList(eventsResponse));
                }
            }
        });
    }

    public void refreshBingoBoard(UUID bingoId, Consumer<Bingo> onSuccess, Consumer<String> onError) {
        if (!hasApiKey()) {
            onError.accept("No API key configured");
            return;
        }

        String apiUrl = config.apiBaseUrl() + "/api/runelite/bingos/" + bingoId;
        Request request = new Request.Builder()
                .url(apiUrl)
                .header("Authorization", "Bearer " + config.apiKey())
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.error("Failed to refresh bingo board", e);
                onError.accept("Failed to refresh bingo board: " + e.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody responseBody = response.body()) {
                    if (!response.isSuccessful() || responseBody == null) {
                        String error = "Unsuccessful response when refreshing bingo: " + response;
                        log.error(error);
                        onError.accept(error);
                        return;
                    }

                    String jsonData = responseBody.string();
                    Bingo updatedBingo = gson.fromJson(jsonData, Bingo.class);
                    onSuccess.accept(updatedBingo);
                }
            }
        });
    }

    public void submitTileCompletion(UUID tileId, byte[] screenshotBytes, Consumer<Bingo> onSuccess, Consumer<String> onError) {
        if (!hasApiKey()) {
            onError.accept("No API key configured");
            return;
        }

        String apiUrl = config.apiBaseUrl() + "/api/runelite/tiles/" + tileId + "/submissions";
        RequestBody requestBody = new MultipartBody.Builder()
                .setType(MultipartBody.FORM)
                .addFormDataPart("image", "screenshot.png", RequestBody.create(MEDIA_TYPE_PNG, screenshotBytes))
                .build();

        Request request = new Request.Builder()
                .url(apiUrl)
                .header("Authorization", "Bearer " + config.apiKey())
                .post(requestBody)
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.error("Failed to submit tile completion", e);
                onError.accept("Failed to submit tile completion: " + e.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody responseBody = response.body()) {
                    String stringBody = responseBody.string();
                    if (!response.isSuccessful()) {
                        ErrorResponse errorResponse = gson.fromJson(stringBody, ErrorResponse.class);
                        String error = errorResponse.getError();
                        log.error("Unsuccessful submission response: {}", error);
                        onError.accept(error);
                        return;
                    }

                    Bingo updatedBingo = gson.fromJson(stringBody, Bingo.class);
                    onSuccess.accept(updatedBingo);
                }
            }
        });
    }

    /**
     * Submits a tile completion automatically with metadata about the source.
     * This uses a dedicated auto-submission endpoint that can automatically assign goals
     * and approve submissions based on the provided metadata.
     */
    public void submitTileAutomatic(UUID tileId, byte[] screenshotBytes, AutoSubmissionMetadata metadata,
                                     Consumer<Bingo> onSuccess, Consumer<String> onError) {
        if (!hasApiKey()) {
            onError.accept("No API key configured");
            return;
        }

        String apiUrl = config.apiBaseUrl() + "/api/runelite/tiles/" + tileId + "/auto-submissions";

        // Convert metadata to JSON
        String metadataJson = gson.toJson(metadata);

        RequestBody requestBody = new MultipartBody.Builder()
                .setType(MultipartBody.FORM)
                .addFormDataPart("image", "screenshot.png", RequestBody.create(MEDIA_TYPE_PNG, screenshotBytes))
                .addFormDataPart("metadata", metadataJson)
                .build();

        Request request = new Request.Builder()
                .url(apiUrl)
                .header("Authorization", "Bearer " + config.apiKey())
                .post(requestBody)
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.error("Failed to submit automatic tile completion", e);
                onError.accept("Failed to submit automatic tile completion: " + e.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody responseBody = response.body()) {
                    String stringBody = responseBody.string();
                    if (!response.isSuccessful()) {
                        ErrorResponse errorResponse = gson.fromJson(stringBody, ErrorResponse.class);
                        String error = errorResponse.getError();
                        log.error("Unsuccessful auto-submission response: {}", error);
                        onError.accept(error);
                        return;
                    }

                    Bingo updatedBingo = gson.fromJson(stringBody, Bingo.class);
                    log.info("Auto-submission successful for tile {}", tileId);
                    onSuccess.accept(updatedBingo);
                }
            }
        });
    }

    public void fetchEvents(Consumer<List<EventData>> onSuccess, Consumer<String> onError) {
        if (!hasApiKey()) {
            onError.accept("No API key configured");
            return;
        }

        String apiUrl = config.apiBaseUrl() + "/api/runelite/events";
        Request request = new Request.Builder()
                .url(apiUrl)
                .header("Authorization", "Bearer " + config.apiKey())
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.error("Failed to fetch events", e);
                onError.accept("Failed to fetch events: " + e.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody responseBody = response.body()) {
                    if (!response.isSuccessful() || responseBody == null) {
                        String error = "Unsuccessful response when fetching events: " + response;
                        log.error(error);
                        onError.accept(error);
                        return;
                    }

                    String jsonData = responseBody.string();
                    EventData[] events = gson.fromJson(jsonData, EventData[].class);
                    onSuccess.accept(Arrays.asList(events));
                }
            }
        });
    }

    private boolean hasApiKey() {
        return config.apiKey() != null && !config.apiKey().isEmpty();
    }
}

package org.bingoscape.services;

import lombok.extern.slf4j.Slf4j;
import org.bingoscape.BingoScapePlugin;
import org.bingoscape.models.Bingo;
import org.bingoscape.models.Goal;
import org.bingoscape.models.GoalTreeNode;
import org.bingoscape.models.Tile;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Matches game events (item drops, skill levels, etc.) to tile requirements
 * to determine when tiles can be auto-submitted.
 *
 * This service queries the current bingo state from the plugin on-demand,
 * ensuring it's always in sync without requiring manual updates.
 */
@Slf4j
@Singleton
public class TileRequirementMatcher {
    // Maps itemId to list of tiles that require that item
    private volatile Map<Integer, List<UUID>> itemToTilesMap = new ConcurrentHashMap<>();

    // Maps itemId to the goal tree nodes that contain it (for checking restrictions)
    private volatile Map<Integer, List<GoalTreeNode>> itemToGoalMap = new ConcurrentHashMap<>();

    // Plugin reference to query current bingo state
    @Inject
    private BingoScapePlugin plugin;

    /**
     * Rebuilds the lookup maps from the current bingo data.
     * Queries the plugin for the current bingo state and parses the goalTree structure
     * to find all item-based goals.
     */
    public void rebuildLookupMaps() {
        Map<Integer, List<UUID>> newItemToTilesMap = new ConcurrentHashMap<>();
        Map<Integer, List<GoalTreeNode>> newItemToGoalMap = new ConcurrentHashMap<>();

        Bingo currentBingo = plugin.getCurrentBingo();
        if (currentBingo == null || currentBingo.getTiles() == null) {
            log.warn("Cannot rebuild maps: currentBingo or tiles is null");
            return;
        }

        log.debug("Rebuilding lookup maps for {} tiles", currentBingo.getTiles().size());

        for (Tile tile : currentBingo.getTiles()) {
            // Skip tiles that are already approved
            if (isTileApproved(tile)) {
                log.debug("Skipping tile {} (already approved)", tile.getId());
                continue;
            }

            // Parse goalTree if available (new API format)
            if (tile.getGoalTree() != null && !tile.getGoalTree().isEmpty()) {
                log.debug("Tile {} has goalTree with {} nodes", tile.getId(), tile.getGoalTree().size());
                parseGoalTreeForItems(tile, tile.getGoalTree(), newItemToTilesMap, newItemToGoalMap);
            }
            // Fallback to flat goals list (backwards compatibility)
//            else if (tile.getGoals() != null && !tile.getGoals().isEmpty()) {
//                log.debug("Tile {} has flat goals list with {} goals", tile.getId(), tile.getGoals().size());
//                for (Goal goal : tile.getGoals()) {
//                    if ("item".equals(goal.getGoalType()) && goal.getItemId() != null) {
//                        itemToTilesMap.computeIfAbsent(goal.getItemId(), k -> new ArrayList<>())
//                                .add(tile.getId());
//                        log.debug("Added item {} -> tile {}", goal.getItemId(), tile.getId());
//                    }
//                }
//            } else {
//                log.debug("Tile {} has no goals or goalTree", tile.getId());
//            }
        }

        itemToTilesMap = newItemToTilesMap;
        itemToGoalMap = newItemToGoalMap;

        log.debug("Built item lookup map with {} unique items mapping to tiles: {}",
            itemToTilesMap.size(), itemToTilesMap.keySet());
    }

    /**
     * Recursively parses a goal tree to find all item goals.
     */
    private void parseGoalTreeForItems(Tile tile, List<GoalTreeNode> nodes, Map<Integer, List<UUID>> newItemToTilesMap, Map<Integer, List<GoalTreeNode>> newItemToGoalMap) {
        if (nodes == null) {
            return;
        }

        for (GoalTreeNode node : nodes) {
            log.debug("Parsing node: type={}, isItemGoal={}, isGroup={}",
                node.getType(), node.isItemGoal(), node.isGroup());

            if (node.isItemGoal() && node.getItemGoal() != null && node.getItemGoal().getItemId() != null) {
                // Found an item goal, add to lookup maps
                int itemId = node.getItemGoal().getItemId();
                newItemToTilesMap.computeIfAbsent(itemId, k -> new ArrayList<>())
                        .add(tile.getId());
                newItemToGoalMap.computeIfAbsent(itemId, k -> new ArrayList<>())
                        .add(node);
                log.debug("Added item {} -> tile {} from goalTree", itemId, tile.getId());
            } else if (node.isGroup() && node.getChildren() != null) {
                // Recursively process child nodes
                log.debug("Recursing into group with {} children", node.getChildren().size());
                parseGoalTreeForItems(tile, node.getChildren(), newItemToTilesMap, newItemToGoalMap);
            } else {
                log.debug("Node skipped: type={}, goalType={}, hasItemGoal={}, hasChildren={}",
                    node.getType(), node.getGoalType(), node.getItemGoal() != null,
                    node.getChildren() != null);
            }
        }
    }

    /**
     * Checks if an item drop matches any tile requirements.
     *
     * @param itemId The OSRS item ID
     * @param npcId  The NPC ID (optional, can be null)
     * @return true if this item is required for any incomplete tile
     */
    public boolean isRequiredItem(int itemId, Integer npcId) {
        Bingo currentBingo = plugin.getCurrentBingo();
        if (currentBingo == null) {
            return false;
        }

        // Check if this item is tracked in our goal map
        List<GoalTreeNode> goalNodes = itemToGoalMap.get(itemId);
        if (goalNodes == null || goalNodes.isEmpty()) {
            return false;
        }

        // Item is tracked - check if any associated tile is not yet approved
        List<UUID> matchingTileIds = itemToTilesMap.get(itemId);
        if (matchingTileIds == null || matchingTileIds.isEmpty()) {
            return false;
        }

        for (UUID tileId : matchingTileIds) {
            Tile tile = getTileById(tileId);
            if (tile != null && !isTileApproved(tile)) {
                // Check if the specific goal for this item is incomplete
                // Only return true if there's at least one incomplete goal for this item
                if (!isGoalCompleteForItem(tile, itemId)) {
                    return true; // Found an incomplete goal that needs this item
                }
            }
        }

        return false;
    }

    /**
     * Gets all tiles that match the given item and optional NPC.
     *
     * @param itemId The OSRS item ID
     * @param npcId  The NPC ID (optional, can be null)
     * @return List of tile IDs that should be auto-submitted
     */
    public List<UUID> getTilesForItem(int itemId, Integer npcId) {
        List<UUID> result = new ArrayList<>();

        Bingo currentBingo = plugin.getCurrentBingo();
        if (currentBingo == null) {
            return result;
        }

        List<UUID> matchingTileIds = itemToTilesMap.get(itemId);
        if (matchingTileIds == null || matchingTileIds.isEmpty()) {
            return result;
        }

        // Check each matching tile
        for (UUID tileId : matchingTileIds) {
            Tile tile = getTileById(tileId);
            if (tile == null || isTileApproved(tile)) {
                continue;
            }

            // CRITICAL: Check if the specific goal for this item is already complete
            // This prevents re-submitting screenshots for goals that are already done
            if (isGoalCompleteForItem(tile, itemId)) {
                log.debug("Skipping tile {} for item {} - goal already complete", tileId, itemId);
                continue;
            }

            // Check if this tile's goals are satisfied
            if (isTileSatisfiedByItem(tile, itemId, npcId)) {
                result.add(tileId);
            }
        }

        return result;
    }

    /**
     * Checks if a tile is relevant for the given item.
     * We don't need to determine if the tile is COMPLETE - just if this item is part of its requirements.
     * The server will validate whether the tile is actually complete after submission.
     */
    private boolean isTileSatisfiedByItem(Tile tile, int itemId, Integer npcId) {
        // The tile is "satisfied" (ready for auto-submission) if:
        // 1. The item is part of ANY goal in the tile's requirements
        // 2. The server will determine if all requirements are met

        // Try goalTree first (new format)
        if (tile.getGoalTree() != null && !tile.getGoalTree().isEmpty()) {
            return containsItemInTree(tile.getGoalTree(), itemId);
        }

        return false;
    }

    /**
     * Recursively checks if an item is part of any goal in the tree.
     * Returns true if the item is relevant to this tile, regardless of AND/OR logic.
     * The server will validate the complete logic after submission.
     */
    private boolean containsItemInTree(List<GoalTreeNode> nodes, int itemId) {
        if (nodes == null || nodes.isEmpty()) {
            return false;
        }

        for (GoalTreeNode node : nodes) {
            if (node.isItemGoal() &&
                node.getItemGoal() != null &&
                node.getItemGoal().getItemId() != null &&
                node.getItemGoal().getItemId() == itemId) {
                // Found the item in this goal
                return true;
            }

            // Recursively check child nodes
            if (node.isGroup() && node.getChildren() != null) {
                if (containsItemInTree(node.getChildren(), itemId)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Checks if a tile has already been approved (to avoid re-submitting).
     */
    private boolean isTileApproved(Tile tile) {
        return tile.getSubmission() != null && "approved".equals(tile.getSubmission().getStatus());
    }

    /**
     * Checks if a specific goal for an item is already complete.
     * Searches the goal tree for goals matching the itemId and checks their completion status.
     *
     * @param tile The tile to check
     * @param itemId The item ID to look for
     * @return true if ALL goals matching this item are already complete
     */
    private boolean isGoalCompleteForItem(Tile tile, int itemId) {
        if (tile.getGoalTree() == null || tile.getGoalTree().isEmpty()) {
            return false;
        }

        // Find all goal nodes matching this item
        List<GoalTreeNode> matchingGoals = findGoalsForItem(tile.getGoalTree(), itemId);

        if (matchingGoals.isEmpty()) {
            return false; // No goals found for this item
        }

        // Check if ALL matching goals are complete
        // (If there are multiple goals for the same item, all must be complete to skip submission)
        for (GoalTreeNode goal : matchingGoals) {
            if (goal.getProgress() == null || !goal.getProgress().isComplete()) {
                return false; // At least one goal is incomplete
            }
        }

        log.debug("All goals for item {} in tile {} are complete", itemId, tile.getId());
        return true; // All goals for this item are complete
    }

    /**
     * Recursively finds all goal nodes matching the given itemId in the goal tree.
     *
     * @param nodes The goal tree nodes to search
     * @param itemId The item ID to find
     * @return List of matching goal nodes
     */
    private List<GoalTreeNode> findGoalsForItem(List<GoalTreeNode> nodes, int itemId) {
        List<GoalTreeNode> result = new ArrayList<>();

        if (nodes == null || nodes.isEmpty()) {
            return result;
        }

        for (GoalTreeNode node : nodes) {
            if (node.isItemGoal() &&
                node.getItemGoal() != null &&
                node.getItemGoal().getItemId() != null &&
                node.getItemGoal().getItemId() == itemId) {
                // Found a matching goal
                result.add(node);
            }

            // Recursively check child nodes
            if (node.isGroup() && node.getChildren() != null) {
                result.addAll(findGoalsForItem(node.getChildren(), itemId));
            }
        }

        return result;
    }

    /**
     * Gets a tile by its ID from the current bingo.
     */
    private Tile getTileById(UUID tileId) {
        Bingo currentBingo = plugin.getCurrentBingo();
        if (currentBingo == null || currentBingo.getTiles() == null) {
            return null;
        }

        return currentBingo.getTiles().stream()
                .filter(t -> t.getId().equals(tileId))
                .findFirst()
                .orElse(null);
    }

    /**
     * Returns true if there are any trackable tiles (tiles with item goals).
     */
    public boolean hasTrackableTiles() {
        return !itemToTilesMap.isEmpty();
    }

    /**
     * Gets statistics about tracked tiles for debugging.
     */
    public String getStats() {
        Bingo currentBingo = plugin.getCurrentBingo();
        if (currentBingo == null) {
            return "No bingo loaded";
        }

        int totalTiles = currentBingo.getTiles() != null ? currentBingo.getTiles().size() : 0;
        int trackableTiles = (int) itemToTilesMap.values().stream()
                .flatMap(List::stream)
                .distinct()
                .count();

        return String.format("Tracking %d items across %d/%d tiles",
                itemToTilesMap.size(), trackableTiles, totalTiles);
    }
}

package org.bingoscape.services;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;
import org.bingoscape.BingoScapeConfig;
import org.bingoscape.BingoScapePlugin;
import org.bingoscape.models.AutoSubmissionMetadata;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Handles automatic tile submissions when game events match tile requirements.
 * Monitors loot events and triggers screenshot + submission when items are
 * obtained.
 */
@Slf4j
@Singleton
public class AutoSubmissionHandler {
    // Track recently submitted tiles to avoid duplicates within a short time window
    private final Map<UUID, Long> recentSubmissions = new ConcurrentHashMap<>();
    private static final long SUBMISSION_COOLDOWN_MS = 5000; // 5 seconds

    @Inject
    private BingoScapePlugin plugin;

    @Inject
    private BingoScapeConfig config;

    @Inject
    private TileRequirementMatcher requirementMatcher;

    @Inject
    private org.bingoscape.notifications.NotificationManager notificationManager;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    /**
     * Handles NPC loot received events (most common source of item drops).
     */
    public void onNpcLootReceived(NpcLootReceived event) {
        if (!shouldProcessEvent()) {
            return;
        }

        NPC npc = event.getNpc();
        int npcId = npc.getId();
        String npcName = npc.getName();

        Collection<ItemStack> items = event.getItems();
        processItemDrops(items, npcId, npcName, "NPC loot");
    }

    /**
     * Handles generic loot received events (pickpocket, event rewards, etc.).
     */
    public void onLootReceived(LootReceived event) {
        if (!shouldProcessEvent()) {
            return;
        }

        // Only process non-NPC loot (NPC loot is handled by onNpcLootReceived)
        if (event.getType() == LootRecordType.NPC) {
            return;
        }

        // For non-NPC loot, we don't have an NPC ID
        Collection<ItemStack> items = event.getItems();
        processItemDrops(items, null, event.getName(), event.getType().name());
    }

    /**
     * Gets the current logged-in RuneScape account name.
     * Uses the plugin's client to get the local player name.
     */
    private String getAccountName() {
        try {
            return plugin.getAccountName();
        } catch (Exception e) {
            log.warn("Failed to get account name", e);
            return null;
        }
    }

    /**
     * Processes a collection of item drops to check if any match tile requirements.
     */
    private void processItemDrops(Collection<ItemStack> items, Integer npcId, String sourceName, String sourceType) {
        if (items == null || items.isEmpty()) {
            return;
        }

        log.debug("Processing {} items from {} ({})", items.size(), sourceName, sourceType);

        for (ItemStack item : items) {
            int itemId = item.getId();
            int quantity = item.getQuantity();

            // Check if this item is required for any tile
            if (requirementMatcher.isRequiredItem(itemId, npcId)) {
                log.info("Found required item {} from {}", itemId, sourceName);

                // Get all tiles that can be completed with this item
                List<UUID> matchingTiles = requirementMatcher.getTilesForItem(itemId, npcId);

                for (UUID tileId : matchingTiles) {
                    // Check cooldown to avoid duplicate submissions
                    if (isOnCooldown(tileId)) {
                        log.debug("Tile {} is on submission cooldown, skipping", tileId);
                        continue;
                    }

                    // Show notification immediately when item is obtained
                    if (config.showAutoSubmitNotifications()) {
                        String itemName = getItemName(itemId);
                        showNotification("Bingo Item", String.format("Obtained %s - auto-submitting...", itemName));
                    }

                    // Submit this tile with full metadata
                    submitTileAutomaticWithMetadata(tileId, itemId, quantity, sourceName, npcId, sourceType);
                }
            }
        }
    }

    /**
     * Automatically submits a tile with a screenshot and metadata.
     */
    private void submitTileAutomatic(UUID tileId, int itemId, int quantity, String sourceName) {
        submitTileAutomaticWithMetadata(tileId, itemId, quantity, sourceName, null, "Unknown");
    }

    /**
     * Automatically submits a tile with a screenshot and full metadata.
     */
    private void submitTileAutomaticWithMetadata(UUID tileId, int itemId, int quantity, String sourceName, Integer npcId,
            String sourceType) {
        log.info("Auto-submitting tile {} for item {} from {}", tileId, itemId, sourceName);

        // Mark this tile as recently submitted
        recentSubmissions.put(tileId, System.currentTimeMillis());

        // Get item name NOW (on client thread) before entering background thread
        // This must be done here because ItemManager requires the client thread
        final String itemName = getItemName(itemId);

        // Capture location data (must be on client thread like getItemName)
        int worldX = 0;
        int worldY = 0;
        int plane = 0;
        int worldNumber = 0;
        int regionId = 0;

        try {
            if (client.getLocalPlayer() != null) {
                WorldPoint location = client.getLocalPlayer().getWorldLocation();
                if (location != null) {
                    worldX = location.getX();
                    worldY = location.getY();
                    plane = location.getPlane();
                    regionId = ((worldX >> 6) << 8) | (worldY >> 6);
                }
            }
            worldNumber = client.getWorld();
        } catch (Exception e) {
            log.debug("Failed to capture location metadata", e);
        }

        // Build metadata
        AutoSubmissionMetadata metadata = AutoSubmissionMetadata.builder()
                .itemId(itemId)
                .quantity(quantity)
                .sourceName(sourceName)
                .npcId(npcId)
                .sourceType(sourceType)
                .accountName(getAccountName())
                .worldX(worldX)
                .worldY(worldY)
                .plane(plane)
                .worldNumber(worldNumber)
                .regionId(regionId)
                .build();

        // Take screenshot and submit with metadata
        plugin.takeScreenshot(tileId, screenshotBytes -> {
            if (screenshotBytes == null) {
                log.error("Failed to capture screenshot for tile {}", tileId);
                showChatMessage("Auto-submission failed: could not capture screenshot");
                return;
            }

            // Submit to API with metadata
            plugin.submitTileAutomaticWithMetadata(tileId, screenshotBytes, metadata);

            // Log success in chatbox (use pre-fetched item name from client thread)
            if (config.showAutoSubmitNotifications()) {
                showChatMessage(String.format("Tile auto-submitted for %s", itemName));
            }
        });
    }

    /**
     * Checks if a tile is currently on submission cooldown.
     */
    private boolean isOnCooldown(UUID tileId) {
        Long lastSubmission = recentSubmissions.get(tileId);
        if (lastSubmission == null) {
            return false;
        }

        long elapsed = System.currentTimeMillis() - lastSubmission;
        if (elapsed > SUBMISSION_COOLDOWN_MS) {
            // Cooldown expired, remove from map
            recentSubmissions.remove(tileId);
            return false;
        }

        return true;
    }

    /**
     * Checks if events should be processed based on config and plugin state.
     */
    private boolean shouldProcessEvent() {
        // Check if auto-submission is enabled
        if (!config.enableAutoSubmission()) {
            log.debug("Auto-submission disabled in config");
            return false;
        }

        // Check if we have a current bingo loaded
        if (plugin.getCurrentBingo() == null) {
            log.debug("No current bingo loaded");
            return false;
        }

        // Check if the requirement matcher has any trackable tiles
        if (!requirementMatcher.hasTrackableTiles()) {
            log.warn("Requirement matcher has no trackable tiles. Stats: {}", requirementMatcher.getStats());
            return false;
        }

        log.debug("Event processing enabled. Trackable tiles: {}", requirementMatcher.getStats());
        return true;
    }

    /**
     * Shows a toast notification to the user.
     */
    private void showNotification(String title, String message) {
        if (!config.showAutoSubmitNotifications()) {
            return;
        }

        // Add toast notification if enabled
        if (config.showToastNotifications()) {
            // Convert Color to RGB int for notification
            int color = config.notificationColor().getRGB() & 0xFFFFFF;
            notificationManager.addNotification(title, message, color);
        }

        // Keep log for debugging
        log.info("Auto-submission notification: {} - {}", title, message);
    }

    /**
     * Shows a notification with default title.
     */
    private void showNotification(String message) {
        showNotification("BingoScape", message);
    }

    /**
     * Shows a message in the game chatbox.
     */
    private void showChatMessage(String message) {
        clientThread.invokeLater(
                () -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "BingoScape: " + message, null));
        log.info("Auto-submission chat message: {}", message);
    }

    /**
     * Gets the display name for an item ID.
     */
    private String getItemName(int itemId) {
        try {
            return plugin.getItemManager().getItemComposition(itemId).getName();
        } catch (Exception e) {
            log.warn("Failed to get item name for ID {}", itemId, e);
            return "Item #" + itemId;
        }
    }

    /**
     * Cleans up old cooldown entries to prevent memory leaks.
     */
    public void cleanupCooldowns() {
        long now = System.currentTimeMillis();
        recentSubmissions.entrySet().removeIf(entry -> now - entry.getValue() > SUBMISSION_COOLDOWN_MS);
    }

    /**
     * Gets statistics about auto-submission for debugging.
     */
    public String getStats() {
        return String.format("Auto-submission: enabled=%s, tiles tracked=%s, recent submissions=%d",
                config.enableAutoSubmission(),
                requirementMatcher.hasTrackableTiles(),
                recentSubmissions.size());
    }
}

package org.bingoscape.models;

import lombok.Data;

import java.time.Instant;
import java.util.Date;
import java.util.List;
import java.util.UUID;

/**
 * Enhanced Tile model to include submission and goals
 */
@Data
public class Tile {
    private UUID id;
    private UUID bingoId;
    private String headerImage;
    private String title;
    private String description;
    private int weight;
    private int index;
    private Integer tier;
    private boolean isHidden;
    private Date createdAt;
    private Date updatedAt;
